#!/usr/bin/env node
/*
 * Markdown -> Word, in the Auriga IT document standard.
 *
 *   node build_word.js <input.md> <output.docx> --doc "User Manual" [--version 1.0.0] [--date "31 October 2026"]
 *
 * Cover page (title, subtitle, metadata block), running header and footers, the
 * Auriga palette, Google Sans Flex with Calibri/Arial fallbacks, and continuous
 * page flow: the only page break is the one after the cover.
 *
 * The Word files in ../word are generated by this script. Edit the Markdown and
 * run `npm run build` in this folder; never edit a .docx by hand.
 */
const fs = require('fs');
const path = require('path');
const JSZip = require('jszip');
const {
  Document, Paragraph, TextRun, ImageRun, ExternalHyperlink, InternalHyperlink, Bookmark,
  Table, TableRow, TableCell, Header, Footer, PageBreak, PageNumber,
  LevelFormat, AlignmentType, BorderStyle, WidthType, ShadingType,
  LineRuleType, TableLayoutType, VerticalAlign, Packer,
} = require('docx');

let sharp = null;
try { sharp = require('sharp'); } catch (e) { /* the text logo is used instead */ }

// ------------------------------------------------------------------ arguments
const args = process.argv.slice(2);
const positional = args.filter((a, i) => !a.startsWith('--') && !(i > 0 && args[i - 1].startsWith('--')));
const flag = (name, fallback) => {
  const i = args.indexOf('--' + name);
  return i >= 0 ? args[i + 1] : fallback;
};
const [INPUT, OUTPUT] = positional;
if (!INPUT || !OUTPUT) {
  console.error('usage: build_word.js <input.md> <output.docx> --doc "User Manual" [--version 1.0.0] [--date "31 October 2026"]');
  process.exit(2);
}
const DOC_NAME = flag('doc', 'Document');
const VERSION = flag('version', '1.0.0');
const DATE = flag('date', new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' }));

const COVER_TITLE = 'Gate Pass Management';
const SUBTITLE = `${DOC_NAME} - Auriga IT Consulting Pvt. Ltd.`;
const METADATA = [
  ['Product', 'Gate Pass Management for ERPNext'],
  ['Platform', 'Frappe / ERPNext v16'],
  ['Document', DOC_NAME],
  ['Version', VERSION],
  ['Date', DATE],
  ['Prepared By', 'Auriga IT Consulting Pvt. Ltd.'],
];

// ------------------------------------------------------------------- constants
const NORMAL = 'Google Sans Flex Normal';
const MEDIUM = 'Google Sans Flex Medium';
const MONO = 'Courier New';
const W = 9602; // content width, DXA
const C = { text: '0f172a', h1: '1E4FA3', h2: '2E6BC4', h3: '437FDB', h4: '6B9FE8', accent: '3F7DDE',
  muted: '64748b', sub: '94a3b8', rule: 'cbd5e1', border: 'cccccc', hdrLine: 'ebf3ff', callout: 'f1f5f9', row: 'FAFAFA' };
const LINE = { line: 240, lineRule: LineRuleType.AUTO };

const LOGO_SVG = `<svg width="1060" height="492" viewBox="0 0 1060 492" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M245.505 248.358L192.751 102.023L139.998 248.358H182.509V267.497H201.886V248.358H245.505ZM252.269 267.497H133.094L63.3333 401.673L192.751 44.6667L321.394 401.673L252.269 267.497Z" fill="#0088FE"/><path d="M401.744 401.563C383.29 401.563 368.596 396.05 357.664 385.022C346.732 373.995 341.115 360.084 340.814 343.29V250.417H354.354V342.076C354.354 354.723 358.918 365.497 368.045 374.4C377.072 383.403 388.255 387.906 401.594 387.906C414.031 387.906 424.787 383.429 433.864 374.475C442.941 365.522 447.48 354.723 447.48 342.076V250.417H461.019V343.29C460.719 360.084 455.102 373.995 444.17 385.022C433.237 396.05 419.095 401.563 401.744 401.563ZM498.722 250.417H512.262V277.581C515.07 273.534 518.33 269.64 522.041 265.896C533.977 253.857 546.212 247.534 558.749 246.927V261.799C550.224 262.204 541.399 267.009 532.272 276.216C519.434 289.064 512.764 304.493 512.262 322.5V399.439H498.722V250.417ZM600.966 250.417V399.439H587.425V250.417H600.966ZM594.195 197.607C597.906 197.607 601.091 198.923 603.748 201.553C606.407 204.184 607.735 207.37 607.735 211.113C607.735 214.958 606.407 218.195 603.748 220.826C601.091 223.456 597.906 224.771 594.195 224.771C590.484 224.771 587.3 223.456 584.642 220.826C581.984 218.195 580.656 214.958 580.656 211.113C580.656 207.37 581.984 204.184 584.642 201.553C587.3 198.923 590.484 197.607 594.195 197.607ZM787.458 306.11C784.849 293.06 778.631 281.578 768.803 271.663C755.463 258.207 739.366 251.48 720.509 251.48C701.654 251.48 685.557 258.207 672.217 271.663C658.878 285.119 652.207 301.356 652.207 320.376C652.207 339.396 658.878 355.633 672.217 369.088C685.557 382.544 701.654 389.271 720.509 389.271C739.366 389.271 755.463 382.544 768.803 369.088C778.531 359.274 784.749 347.893 787.458 334.944V306.11ZM787.157 369.847C784.649 373.085 781.941 376.221 779.032 379.255C762.884 395.544 743.377 403.688 720.509 403.688C697.742 403.688 678.285 395.544 662.137 379.255C645.989 362.968 637.916 343.341 637.916 320.376C637.916 297.309 645.989 277.657 662.137 261.42C678.285 245.182 697.742 237.063 720.509 237.063C743.377 237.063 762.884 245.157 779.032 261.343C782.142 264.581 785.001 267.971 787.608 271.511V250.417H801.148V366.205C801.148 388.563 793.275 407.684 777.528 423.567C761.381 439.856 741.923 448 719.156 448C696.288 448 676.781 439.856 660.633 423.567C657.323 420.229 654.365 416.739 651.756 413.097L666.049 407.937C667.554 409.758 669.158 411.529 670.862 413.248C684.203 426.704 700.299 433.431 719.156 433.431C737.911 433.431 753.959 426.704 767.298 413.248C779.434 401.007 786.053 386.54 787.157 369.847ZM996.667 399.439H983.127V369.088C980.52 372.629 977.661 376.019 974.551 379.255C958.403 395.544 938.896 403.688 916.028 403.688C893.261 403.688 873.804 395.544 857.656 379.255C841.508 362.968 833.435 343.341 833.435 320.376C833.435 297.309 841.508 277.632 857.656 261.343C873.804 245.056 893.261 236.911 916.028 236.911C938.896 236.911 958.403 245.056 974.551 261.343C977.661 264.581 980.52 267.971 983.127 271.511V250.417H996.667V399.439ZM983.127 333.881V306.87C980.62 293.515 974.351 281.78 964.322 271.663C950.981 258.207 934.885 251.48 916.028 251.48C897.173 251.48 881.076 258.207 867.736 271.663C854.397 285.119 847.726 301.356 847.726 320.376C847.726 339.396 854.397 355.607 867.736 369.012C881.076 382.418 897.173 389.12 916.028 389.12C934.885 389.12 950.981 382.392 964.322 368.937C974.351 358.82 980.62 347.135 983.127 333.881Z" fill="#0D0D0D"/></svg>`;

// In-document links: Markdown writes them as [text](#github-style-slug), so each
// heading gets a bookmark and the slug maps to it.
const anchors = new Map();
const ghSlug = (t) => t.toLowerCase().replace(/[`*_]/g, '').replace(/[^\p{L}\p{N}\s-]/gu, '').trim().replace(/\s/g, '-');

// ------------------------------------------------------------- text utilities
const noDashes = (s) => s.replace(/\s*[—–]\s*/g, ' - ').replace(/\n/g, ' ');

// Inline Markdown: `code`, **bold**, *italic*, [text](url). Bold uses the Medium weight.
function inline(text, base = {}) {
  text = noDashes(text);
  const out = [];
  const rules = [
    { re: /`([^`]+)`/, make: (m) => [new TextRun({ text: m[1], font: MONO, size: base.size ? base.size - 2 : 20, color: base.color || C.text, italics: base.italics })] },
    { re: /\*\*([^*]+)\*\*/, make: (m) => inline(m[1], { ...base, bold: true }) },
    { re: /(?<![*\w])\*([^*\s][^*]*?)\*(?![*\w])/, make: (m) => inline(m[1], { ...base, italics: true }) },
    { re: /\[([^\]]+)\]\(([^)]+)\)/, make: (m) => {
      const linkRun = new TextRun({ text: m[1], font: NORMAL, size: base.size || 22, color: C.accent, underline: {} });
      if (!m[2].startsWith('#')) return [new ExternalHyperlink({ link: m[2], children: [linkRun] })];
      const target = anchors.get(m[2].slice(1));
      return target ? [new InternalHyperlink({ anchor: target, children: [linkRun] })] : inline(m[1], base);
    } },
  ];
  let rest = text;
  while (rest.length) {
    let best = null;
    for (const r of rules) {
      const m = r.re.exec(rest);
      if (m && (!best || m.index < best.m.index)) best = { r, m };
    }
    if (!best) { out.push(run(rest, base)); break; }
    if (best.m.index > 0) out.push(run(rest.slice(0, best.m.index), base));
    out.push(...best.r.make(best.m));
    rest = rest.slice(best.m.index + best.m[0].length);
  }
  return out;
}
function run(text, o) {
  return new TextRun({
    text, font: o.bold ? MEDIUM : NORMAL, bold: false, italics: !!o.italics,
    size: o.size || 22, color: o.color || C.text,
  });
}

// --------------------------------------------------------------- markdown -> blocks
function parse(md) {
  const lines = md.replace(/\r/g, '').split('\n');
  const blocks = [];
  let i = 0;
  const isTableRow = (l) => /^\s*\|.*\|\s*$/.test(l);
  const isSep = (l) => /^\s*\|[\s:|-]+\|\s*$/.test(l);
  const cells = (l) => l.trim().replace(/^\||\|$/g, '').split(/(?<!\\)\|/).map((c) => c.trim().replace(/\\\|/g, '|'));
  while (i < lines.length) {
    const l = lines[i];
    if (!l.trim()) { i++; continue; }
    if (/^```/.test(l)) {                                   // code fence
      const code = []; i++;
      while (i < lines.length && !/^```/.test(lines[i])) code.push(lines[i++]);
      i++; blocks.push({ t: 'code', lines: code }); continue;
    }
    if (/^-{3,}\s*$/.test(l)) { i++; continue; }            // rules: continuous flow, no visual rule
    const h = /^(#{1,4})\s+(.*)$/.exec(l);
    if (h) { blocks.push({ t: 'h', level: h[1].length, text: h[2].trim() }); i++; continue; }
    if (isTableRow(l) && i + 1 < lines.length && isSep(lines[i + 1])) {
      const header = cells(l); i += 2; const rows = [];
      while (i < lines.length && isTableRow(lines[i])) rows.push(cells(lines[i++]));
      blocks.push({ t: 'table', header, rows }); continue;
    }
    if (/^>\s?/.test(l)) {                                  // blockquote -> callout
      const paras = []; let cur = [];
      while (i < lines.length && /^>/.test(lines[i])) {
        const body = lines[i].replace(/^>\s?/, '');
        if (!body.trim()) { if (cur.length) paras.push(cur.join(' ')); cur = []; } else cur.push(body.trim());
        i++;
      }
      if (cur.length) paras.push(cur.join(' '));
      blocks.push({ t: 'callout', paras }); continue;
    }
    const li = /^(\s*)([-*]|\d+\.)\s+(.*)$/.exec(l);
    if (li) {                                               // list
      const ordered = /\d/.test(li[2]); const items = [];
      while (i < lines.length) {
        const m = /^(\s*)([-*]|\d+\.)\s+(.*)$/.exec(lines[i]);
        if (m && (/\d/.test(m[2]) === ordered || m[1].length >= 2)) {
          items.push({ level: m[1].length >= 2 ? 1 : 0, text: m[3].trim() }); i++;
          while (i < lines.length && /^\s{2,}\S/.test(lines[i]) && !/^\s*([-*]|\d+\.)\s+/.test(lines[i])) {
            items[items.length - 1].text += ' ' + lines[i].trim(); i++;
          }
        } else break;
      }
      blocks.push({ t: 'list', ordered, items }); continue;
    }
    const para = [];                                        // paragraph
    while (i < lines.length && lines[i].trim() && !/^(#{1,4}\s|```|>|\s*\|.*\|\s*$|-{3,}\s*$)/.test(lines[i]) && !/^\s*([-*]|\d+\.)\s+/.test(lines[i])) para.push(lines[i++].trim());
    if (para.length) blocks.push({ t: 'p', text: para.join(' ') });
  }
  return blocks;
}

// ------------------------------------------------------------------- builders
const HEAD = {
  1: { style: 'Heading1', size: 48, color: C.h1, before: 240, after: 115 },
  2: { style: 'Heading2', size: 36, color: C.h2, before: 200, after: 92 },
  3: { style: 'Heading3', size: 28, color: C.h3, before: 160, after: 69 },
  4: { style: 'Heading4', size: 24, color: C.h4, before: 120, after: 46 },
};
function heading(level, text, bookmark) {
  const h = HEAD[level];
  const label = new TextRun({ text: noDashes(text), font: MEDIUM, bold: true, italics: false, size: h.size, color: h.color });
  return new Paragraph({
    style: h.style, keepNext: true,
    spacing: { before: h.before, after: h.after, ...LINE },
    children: [bookmark ? new Bookmark({ id: bookmark, children: [label] }) : label],
  });
}
const bodyPara = (text) => {
  if (/^note:/i.test(text)) {
    return new Paragraph({ spacing: { before: 0, after: 100, ...LINE }, children: [
      new TextRun({ text: 'Note: ', font: MEDIUM, bold: true, italics: true, size: 22, color: '212A42' }),
      ...inline(text.replace(/^note:\s*/i, ''), { italics: true, color: C.muted }),
    ] });
  }
  return new Paragraph({ spacing: { before: 0, after: 150, ...LINE }, children: inline(text) });
};
const none = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const line = (color, size = 4) => ({ style: BorderStyle.SINGLE, size, color });

function weights(header, rows) {
  const n = header.length;
  const w = header.map((h, c) => {
    const longest = Math.max(h.length, ...rows.map((r) => (r[c] || '').replace(/[`*]/g, '').length));
    const avg = rows.length ? rows.reduce((a, r) => a + (r[c] || '').length, 0) / rows.length : 10;
    const need = Math.max(h.length * 150 + 330, 700);                 // header never wraps
    return { need, want: Math.min(Math.max(avg * 1.1, longest * 0.45, 8), 70) };
  });
  const totalWant = w.reduce((a, x) => a + x.want, 0);
  let widths = w.map((x) => Math.max(x.need, Math.round((x.want / totalWant) * W)));
  let sum = widths.reduce((a, b) => a + b, 0);
  while (sum !== W) {                                                  // scale the roomy columns to fit
    const diff = W - sum; const idx = widths.map((v, k) => [v - w[k].need, k]).sort((a, b) => b[0] - a[0])[0][1];
    widths[idx] += diff; sum += diff;
    if (widths[idx] < w[idx].need && n > 1) { widths[idx] = w[idx].need; break; }
  }
  const fix = W - widths.reduce((a, b) => a + b, 0); widths[widths.indexOf(Math.max(...widths))] += fix;
  return widths;
}
function table(header, rows) {
  const widths = weights(header, rows);
  const label = header.length === 2;
  const pad = { top: 144, left: 144, bottom: 144, right: 144 };
  const borders = { top: line(C.border), bottom: line(C.border), left: line(C.border), right: line(C.border) };
  const cell = (text, c, head, first) => new TableCell({
    width: { size: widths[c], type: WidthType.DXA }, borders, margins: pad, verticalAlign: VerticalAlign.TOP,
    shading: { type: ShadingType.CLEAR, color: 'auto', fill: head ? C.accent : C.row },
    children: [new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: head
      ? [new TextRun({ text: noDashes(text), font: MEDIUM, bold: false, size: 24, color: 'ffffff' })]
      : inline(text, { bold: label && first, size: 22 }) })],
  });
  return new Table({
    width: { size: W, type: WidthType.DXA }, columnWidths: widths, layout: TableLayoutType.FIXED,
    rows: [
      new TableRow({ tableHeader: true, cantSplit: true, children: header.map((h, c) => cell(h, c, true, c === 0)) }),
      ...rows.map((r) => new TableRow({ cantSplit: true, children: header.map((_, c) => cell(r[c] || '', c, false, c === 0)) })),
    ],
  });
}
const spacer = (after = 120) => new Paragraph({ spacing: { before: 0, after, ...LINE }, children: [] });
function callout(paras) {
  return [new Table({
    width: { size: W, type: WidthType.DXA }, columnWidths: [W], layout: TableLayoutType.FIXED,
    rows: [new TableRow({ cantSplit: true, children: [new TableCell({
      width: { size: W, type: WidthType.DXA },
      borders: { top: none, bottom: none, right: none, left: line(C.accent, 24) },
      shading: { type: ShadingType.CLEAR, color: 'auto', fill: C.callout },
      margins: { top: 144, left: 216, bottom: 144, right: 216 },
      children: paras.map((p, k) => new Paragraph({ spacing: { before: 0, after: k === paras.length - 1 ? 0 : 100, ...LINE }, children: inline(p) })),
    })] })],
  }), spacer(150)];
}
function codeBlock(lines) {
  return [new Table({
    width: { size: W, type: WidthType.DXA }, columnWidths: [W], layout: TableLayoutType.FIXED,
    rows: [new TableRow({ children: [new TableCell({
      width: { size: W, type: WidthType.DXA },
      borders: { top: line(C.border), bottom: line(C.border), left: line(C.border), right: line(C.border) },
      shading: { type: ShadingType.CLEAR, color: 'auto', fill: C.row },
      margins: { top: 144, left: 216, bottom: 144, right: 216 },
      children: (lines.length ? lines : ['']).map((l) => new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [new TextRun({ text: noDashes(l) || ' ', font: MONO, size: 18, color: C.text })] })),
    })] })],
  }), spacer(150)];
}

let listCounter = 0;
const numberingRefs = [];
function list(block) {
  let ref = 'bullets';
  if (block.ordered) { ref = `num-${++listCounter}`; numberingRefs.push(ref); }
  return block.items.map((it) => new Paragraph({
    numbering: { reference: ref, level: it.level },
    spacing: { before: it.level ? 60 : 80, after: 40, ...LINE },
    children: inline(it.text, { size: 20 }),
  })).concat(spacer(60));
}

function bodyChildren(md) {
  const out = [];
  const blocks = parse(md);
  const seen = new Map(); let n = 0;
  for (const b of blocks) {
    if (b.t !== 'h') continue;
    let slug = ghSlug(b.text); const k = seen.get(slug) || 0; seen.set(slug, k + 1);
    if (k) slug += '-' + k;
    b.bookmark = 'bm_' + (++n); anchors.set(slug, b.bookmark);
  }
  for (const b of blocks) {
    if (b.t === 'h') out.push(heading(b.level, b.text, b.bookmark));
    else if (b.t === 'p') out.push(bodyPara(b.text));
    else if (b.t === 'list') out.push(...list(b));
    else if (b.t === 'table') out.push(table(b.header, b.rows), spacer(150));
    else if (b.t === 'callout') out.push(...callout(b.paras));
    else if (b.t === 'code') out.push(...codeBlock(b.lines));
  }
  return out;
}

// ------------------------------------------------------- header / footer / cover
const small = (text, o = {}) => new TextRun({ text, font: NORMAL, size: 18, color: C.muted, ...o });
const noBorders = { top: none, bottom: none, left: none, right: none };
const zeroMargins = { top: 0, bottom: 0, left: 0, right: 0 };

function logoRun(png, widthPx) {
  return new ImageRun({ data: png, type: 'png', transformation: { width: widthPx, height: Math.round(widthPx / 2.154) } });
}
const logoFallback = (size = 24) => new TextRun({ text: 'Auriga IT', font: MEDIUM, bold: false, size, color: C.accent });

async function build() {
  const md = fs.readFileSync(INPUT, 'utf8');
  const logoHeader = sharp ? await sharp(Buffer.from(LOGO_SVG)).resize(192, null).png().toBuffer() : null;
  const logoCover = sharp ? await sharp(Buffer.from(LOGO_SVG)).resize(422, null).png().toBuffer() : null;

  const bodyHeader = new Header({ children: [
    spacer(0),
    new Table({
      width: { size: W, type: WidthType.DXA }, columnWidths: [4602, 5000], layout: TableLayoutType.FIXED,
      borders: { ...noBorders, insideHorizontal: none, insideVertical: none },
      rows: [new TableRow({ children: [
        new TableCell({ width: { size: 4602, type: WidthType.DXA }, margins: zeroMargins, borders: { ...noBorders, bottom: line(C.hdrLine) },
          children: [new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [logoHeader ? logoRun(logoHeader, 96) : logoFallback(24)] })] }),
        new TableCell({ width: { size: 5000, type: WidthType.DXA }, margins: zeroMargins, borders: { ...noBorders, bottom: line(C.hdrLine) },
          children: [
            new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [] }),
            new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { before: 0, after: 0, ...LINE }, children: [small(COVER_TITLE)] }),
          ] }),
      ] })],
    }),
    spacer(0),
  ] });
  const coverHeader = new Header({ children: [spacer(0)] });

  const defaultFooter = new Footer({ children: [
    spacer(0),
    new Table({
      width: { size: W, type: WidthType.DXA }, columnWidths: [4801, 4801], layout: TableLayoutType.FIXED,
      borders: { ...noBorders, insideHorizontal: none, insideVertical: none },
      rows: [new TableRow({ children: [
        new TableCell({ width: { size: 4801, type: WidthType.DXA }, margins: { top: 80, bottom: 0, left: 0, right: 0 }, borders: { ...noBorders, top: line(C.rule) },
          children: [new Paragraph({ alignment: AlignmentType.LEFT, spacing: { before: 0, after: 0, ...LINE }, children: [small('aurigait.com')] })] }),
        new TableCell({ width: { size: 4801, type: WidthType.DXA }, margins: { top: 80, bottom: 0, left: 0, right: 0 }, borders: { ...noBorders, top: line(C.rule) },
          children: [new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { before: 0, after: 0, ...LINE }, children: [new TextRun({ children: ['Page ', PageNumber.CURRENT], font: NORMAL, size: 18, color: C.muted })] })] }),
      ] })],
    }),
    spacer(0),
  ] });

  const addr = (text, after = 40) => new Paragraph({ spacing: { before: 0, after, ...LINE }, children: [small(text)] });
  const coverFooter = new Footer({ children: [
    new Paragraph({ spacing: { before: 0, after: 60, ...LINE }, children: [] }),
    new Table({
      width: { size: W, type: WidthType.DXA }, columnWidths: [6517, 3085], layout: TableLayoutType.FIXED,
      borders: { ...noBorders, insideHorizontal: none, insideVertical: none },
      rows: [new TableRow({ children: [
        new TableCell({ width: { size: 6517, type: WidthType.DXA }, margins: { top: 80, bottom: 0, left: 0, right: 0 }, verticalAlign: VerticalAlign.TOP, borders: { ...noBorders, top: line(C.rule) },
          children: [
            new Paragraph({ spacing: { before: 0, after: 40, ...LINE }, children: [new TextRun({ text: 'Auriga IT Consulting Pvt Ltd', font: MEDIUM, bold: false, size: 22, color: C.text })] }),
            addr('Reg Add: 111/306 Agarwal Farm Mansarovar, Jaipur, Rajasthan - 302020'),
            addr('Branch: G1-227/228, Export Promotion Industrial Park, IT Park Rd, Sitapura, Jaipur, Rajasthan 302022', 0),
          ] }),
        new TableCell({ width: { size: 3085, type: WidthType.DXA }, margins: { top: 72, bottom: 72, left: 0, right: 0 }, verticalAlign: VerticalAlign.TOP, borders: { ...noBorders, top: line(C.rule) },
          children: [
            new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { before: 0, after: 40, ...LINE }, children: [small('CIN: U72200RJ201OPTC03079')] }),
            new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { before: 0, after: 40, ...LINE }, children: [small('contactus@aurigait.com')] }),
            new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { before: 0, after: 0, ...LINE }, children: [
              new ExternalHyperlink({ link: 'https://www.aurigait.com', children: [new TextRun({ text: 'www.aurigait.com', font: NORMAL, size: 18, color: C.accent, underline: {} })] })] }),
          ] }),
      ] })],
    }),
    new Paragraph({ spacing: { before: 0, after: 60, ...LINE }, children: [] }),
  ] });

  const meta = new Table({
    width: { size: W, type: WidthType.DXA }, columnWidths: [W], layout: TableLayoutType.FIXED,
    rows: [new TableRow({ children: [new TableCell({
      width: { size: W, type: WidthType.DXA },
      borders: { top: none, bottom: none, right: none, left: line(C.accent, 24) },
      shading: { type: ShadingType.CLEAR, color: 'auto', fill: C.callout },
      margins: { top: 288, left: 288, bottom: 288, right: 288 },
      children: METADATA.map(([k, v]) => new Paragraph({ spacing: { before: 0, after: 80, line: 276, lineRule: LineRuleType.AUTO }, children: [
        new TextRun({ text: `${k}: `, font: MEDIUM, bold: false, size: 28, color: C.text }),
        new TextRun({ text: v, font: NORMAL, size: 28, color: C.text }),
      ] })),
    })] })],
  });

  const cover = [
    new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [new TextRun({ text: '​', size: 120 })] }),
    new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [logoCover ? logoRun(logoCover, 211) : logoFallback(32)] }),
    new Paragraph({ spacing: { before: 0, after: 0, ...LINE }, children: [new TextRun({ text: '​', size: 88 })] }),
    new Paragraph({ spacing: { before: 0, after: 20, lineRule: LineRuleType.AUTO }, children: [new TextRun({ text: COVER_TITLE, font: MEDIUM, bold: false, size: 88, color: C.accent })] }),
    new Paragraph({ spacing: { before: 0, after: 800 }, children: [new TextRun({ text: SUBTITLE, font: NORMAL, size: 36, color: C.sub })] }),
    meta,
    new Paragraph({ children: [new PageBreak()] }),                    // the one structural break: cover -> body
  ];

  const body = bodyChildren(md);
  const levelsBullets = [
    { level: 0, format: LevelFormat.BULLET, text: '●', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } }, run: { size: 20, font: NORMAL } } },
    { level: 1, format: LevelFormat.BULLET, text: '–', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 1080, hanging: 360 } }, run: { size: 20, font: NORMAL } } },
  ];
  const numbered = (ref) => ({ reference: ref, levels: [
    { level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } }, run: { size: 20, font: NORMAL } } },
    { level: 1, format: LevelFormat.LOWER_LETTER, text: '%2.', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 1080, hanging: 360 } }, run: { size: 20, font: NORMAL } } },
  ] });

  const heading1 = (id, name, size, color, before, after) => ({
    id, name, basedOn: 'Normal', next: 'Normal', quickFormat: true,
    run: { font: MEDIUM, bold: true, italics: false, size, color },
    paragraph: { spacing: { before, after, ...LINE }, keepNext: true },
  });
  const doc = new Document({
    creator: 'Auriga IT Consulting Pvt. Ltd.', title: `${COVER_TITLE} - ${DOC_NAME}`,
    styles: {
      default: { document: { run: { font: NORMAL, size: 22, color: C.text }, paragraph: { spacing: { before: 0, after: 150, ...LINE } } } },
      paragraphStyles: [
        heading1('Heading1', 'Heading 1', 48, C.h1, 240, 115), heading1('Heading2', 'Heading 2', 36, C.h2, 200, 92),
        heading1('Heading3', 'Heading 3', 28, C.h3, 160, 69), heading1('Heading4', 'Heading 4', 24, C.h4, 120, 46),
      ],
    },
    numbering: { config: [{ reference: 'bullets', levels: levelsBullets }, ...numberingRefs.map(numbered)] },
    sections: [{
      properties: {
        titlePage: true,
        page: { size: { width: 11906, height: 16838 }, margin: { top: 288, bottom: 288, left: 1152, right: 1152, header: 144, footer: 144, gutter: 0 }, pageNumbers: { start: 0 } },
      },
      headers: { first: coverHeader, default: bodyHeader },
      footers: { first: coverFooter, default: defaultFooter },
      children: [...cover, ...body],
    }],
  });

  // docx cannot write <w:altName>, so the font table is rewritten after packing.
  const zip = await JSZip.loadAsync(await Packer.toBuffer(doc));
  zip.file('word/fontTable.xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:fonts xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:font w:name="Google Sans Flex Medium"><w:altName w:val="Calibri"/><w:family w:val="swiss"/><w:pitch w:val="variable"/></w:font>
  <w:font w:name="Google Sans Flex Normal"><w:altName w:val="Arial"/><w:family w:val="swiss"/><w:pitch w:val="variable"/></w:font>
</w:fonts>`);
  fs.mkdirSync(path.dirname(path.resolve(OUTPUT)), { recursive: true });
  fs.writeFileSync(OUTPUT, await zip.generateAsync({ type: 'nodebuffer' }));
  console.log(`wrote ${OUTPUT}${sharp ? '' : ' (text logo: install sharp for the image)'}`);
}
build().catch((e) => { console.error(e); process.exit(1); });
